一个武器 Actor 用普通 struct 记录命中过的目标，跑几分钟后这些目标“偶发消失”，有时指针直接悬空。请说明成因，并分别给出“保活”和“不保活”两种修法。

```cpp
struct FHitRecord
{
    TArray<TObjectPtr<AActor>> Targets;   // 期望这些目标被保活
};

UCLASS()
class AMyWeapon : public AActor
{
    GENERATED_BODY()
public:
    void RecordHit(AActor* Hit);
private:
    FHitRecord HitRecord;                // 普通成员，没有 UPROPERTY
};

void AMyWeapon::RecordHit(AActor* Hit)
{
    if (IsValid(Hit)) { HitRecord.Targets.Add(Hit); }
}
