AI 组件为了省掉每帧回查，把弱指针 `Get()` 的结果缓存成裸指针成员，目标被 Destroy 并经过 GC 后访问崩溃。请指出问题并给出正确写法。

```cpp
UCLASS()
class UAITargetingComponent : public UActorComponent
{
    GENERATED_BODY()
public:
    void SetTarget(AActor* InTarget) { WeakTarget = InTarget; }

    virtual void TickComponent(float Dt, ELevelTick Type,
        FActorComponentTickFunction* Fn) override
    {
        Super::TickComponent(Dt, Type, Fn);
        if (!CachedTarget)                  // 只取一次，之后一直复用
        {
            CachedTarget = WeakTarget.Get();
        }
        if (CachedTarget)
        {
            MoveToward(CachedTarget->GetActorLocation());
        }
    }
private:
    UPROPERTY() TWeakObjectPtr<AActor> WeakTarget;
    AActor* CachedTarget = nullptr;          // 裸指针成员
};
```

