Actor 只在 `Reason == Destroyed` 时清理定时器和子系统注册，切关卡后旧对象仍在被回调。请指出问题，并给出与 Reason 无关的正确写法。

```cpp
void AMyActor::EndPlay(const EEndPlayReason::Type Reason)
{
    UE_LOG(LogTemp, Log, TEXT("[EndPlay] %d"), static_cast<int32>(Reason));
    if (Reason == EEndPlayReason::Destroyed)
    {
        GetWorldTimerManager().ClearTimer(Handle);
        if (UMySubsystem* S = GetWorld()->GetSubsystem<UMySubsystem>())
        {
            S->Unregister(this);
        }
    }
    Super::EndPlay(Reason);
}
```

组件在 `OnRegister` 里向子系统订阅回合事件，PIE 反复进出后一次事件会触发多次。请说明原因，并给出两种改法。

```cpp
UCLASS()
class UMyPulseComponent : public UActorComponent
{
    GENERATED_BODY()
public:
    UMyPulseComponent()
    {
        PrimaryComponentTick.bCanEverTick = true;
        bWantsInitializeComponent = true;
    }
    virtual void OnRegister() override
    {
        Super::OnRegister();
        if (UMyRoundSubsystem* S = GetWorld()->GetSubsystem<UMyRoundSubsystem>())
        {
            S->OnRoundStart.AddDynamic(this, &UMyPulseComponent::HandleRound);
        }
    }
    virtual void EndPlay(const EEndPlayReason::Type Reason) override
    {
        Super::EndPlay(Reason);      // 只调了 Super，没有解绑
    }
    UFUNCTION() void HandleRound();
};
```

